mapper.select:
/* selectMasterMdCmCatalogReqList */ SELECT Z.BUYER ,Z.BUYER_NAME_LOC ,Z.REQ_NO ,Z.STATUS ,Z.STATUS_NM ,Z.BUYER_ITEM_NO ,Z.AGENT ,Z.AGENT_NAME_LOC ,Z.KEP_USER_NAME ,Z.DEPARTMENT_NAME ,Z.KEP_USER_ID ,Z.CMS_CATLG_ID ,Z.ADD_DATE ,Z.ADD_USER_ID ,Z.CHANGE_DATE ,Z.CHANGE_USER_ID ,Z.REVISION ,Z.DESCRIPTION_LOC ,Z.SPECIFICATION ,Z.MAKER_CODE ,Z.MAKER_NAME ,Z.ORIGIN_CODE ,Z.ORIGIN_NAME ,Z.UNIT_MEASURE ,Z.IMGFILE_DIR ,Z.IMGFILE_NAME ,Z.IMGFILE_NAME_IMG ,Z.SG_NAME ,Z.SG_ID ,Z.CMS_CATEG_NAME ,Z.CMS_CATEG_ID ,Z.S_DESCRIPTION_LOC ,Z.S_SPECIFICATION ,Z.S_MAKER_CODE ,Z.S_MAKER_NAME ,Z.S_ORIGIN_CODE ,Z.S_ORIGIN_NAME ,Z.S_UNIT_MEASURE ,Z.S_IMGFILE_DIR ,Z.S_IMGFILE_NAME ,Z.S_IMGFILE_NAME_IMG ,Z.ATOS_REMARK ,Z.STOA_REMARK ,Z.ATOS_REMARK_IMG ,Z.STOA_REMARK_IMG ,Z.CONTRACT_YN ,Z.REJECT_REMARK ,Z.BYCA_COMORG_CODE ,Z.MSDS_YN ,Z.S_MSDS_YN ,Z.IMAGE_KEY ,Z.IMAGE_KEY_IMG ,Z.ITEM_TYPE ,Z.ITEM_TYPE_NM ,Z.CATALOG_CHOICE_TYPE ,Z.CATALOG_CHOICE_TYPE_NM ,Z.BYIT_STATUS ,Z.JOB_TYPE ,Z.JOB_TYPE_NM ,Z.S_MAKER_PART_NO FROM( SELECT A.BUYER ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.BUYER) AS BUYER_NAME_LOC ,A.REQ_NO ,A.STATUS ,(SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M152' AND COD.CODE = A.STATUS) AS STATUS_NM ,A.BUYER_ITEM_NO ,A.AGENT ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.AGENT) AS AGENT_NAME_LOC ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =A.KEP_USER_ID) AS KEP_USER_NAME ,(SELECT COD.TEXT1 FROM ICOMCOD2 COD, ICOMLUSR USR WHERE COD.COMPANY_CODE = 'KRKORE0001' AND COD.TYPE = 'C001' AND COD.CODE = USR.DEPARTMENT AND USR.USER_ID = A.KEP_USER_ID) AS DEPARTMENT_NAME ,A.KEP_USER_ID ,DECODE(A.CMS_CATLG_ID,'',DECODE(D.CMS_CATLG_ID,'NO_CATLG','',D.CMS_CATLG_ID), A.CMS_CATLG_ID) AS CMS_CATLG_ID ,A.ADD_DATE ,A.ADD_USER_ID ,A.CHANGE_DATE ,A.CHANGE_USER_ID ,B.REVISION ,D.DESCRIPTION_LOC ,D.SPECIFICATION ,D.MAKER_CODE ,D.MAKER_NAME ,D.ORIGIN_CODE ,(SELECT COD.TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M001' AND COD.CODE = D.ORIGIN_CODE) AS ORIGIN_NAME ,D.UNIT_MEASURE ,D.IMGFILE_DIR ,D.IMGFILE_NAME ,DECODE(TRIM(D.IMGFILE_NAME),'','2','3') AS IMGFILE_NAME_IMG ,(SELECT SG_NAME FROM KEPSGMG WHERE SG_ID = (SELECT SG_ID FROM CMSCATEG WHERE CMS_CATEG_ID = D.CMS_CATEG_ID)) AS SG_NAME ,(SELECT SG_ID FROM CMSCATEG WHERE CMS_CATEG_ID = D.CMS_CATEG_ID) AS SG_ID ,(SELECT CATEG_NAME FROM CMSCATEG WHERE CMS_CATEG_ID = D.CMS_CATEG_ID) AS CMS_CATEG_NAME ,D.CMS_CATEG_ID ,B.DESCRIPTION_LOC AS S_DESCRIPTION_LOC ,B.SPECIFICATION AS S_SPECIFICATION ,B.MAKER_CODE AS S_MAKER_CODE ,B.MAKER_NAME AS S_MAKER_NAME ,B.ORIGIN_CODE AS S_ORIGIN_CODE ,(SELECT COD.TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M001' AND COD.CODE = B.ORIGIN_CODE) AS S_ORIGIN_NAME ,B.UNIT_MEASURE AS S_UNIT_MEASURE ,B.IMGFILE_DIR AS S_IMGFILE_DIR ,B.IMGFILE_NAME AS S_IMGFILE_NAME ,DECODE(TRIM(B.IMGFILE_NAME),'','2','3') AS S_IMGFILE_NAME_IMG ,A.ATOS_REMARK ,B.STOA_REMARK ,DECODE(A.ATOS_REMARK,'','0','1') AS ATOS_REMARK_IMG ,DECODE(B.STOA_REMARK,'','0','1') AS STOA_REMARK_IMG ,DECODE(NVL((SELECT COUNT(*) FROM ICOMCQDT CQDT WHERE CQDT.BUYER = D.BUYER AND CQDT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CQDT.AGENT = A.AGENT AND STATUS != 'D'),0),0,'N','Y') AS CONTRACT_YN , A.REJECT_REMARK , C.BYCA_COMORG_CODE , D.MSDS_YN , B.MSDS_YN AS S_MSDS_YN , B.IMAGE_KEY , DECODE(TRIM(B.IMAGE_KEY),'',2,3) AS IMAGE_KEY_IMG , A.ITEM_TYPE , DECODE(A.ITEM_TYPE,'S','신규','기존') AS ITEM_TYPE_NM , D.CATALOG_CHOICE_TYPE , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'DQCT' AND CODE = D.CATALOG_CHOICE_TYPE AND FLAG = 'Y') AS CATALOG_CHOICE_TYPE_NM , DECODE(D.STATUS, 'D', '삭제', '사용') AS BYIT_STATUS , A.JOB_TYPE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='M158' AND COD.CODE = A.JOB_TYPE) AS JOB_TYPE_NM , B.MAKER_PART_NO AS S_MAKER_PART_NO FROM KEPCMSHD A, KEPCMSDT B, ICOMCMPY C, ICOMBYIT D WHERE A.BUYER = B.BUYER(+) AND A.REQ_NO = B.REQ_NO(+) AND B.STATUS (+)!= 'O' AND A.BUYER = C.COM_CODE AND C.BYCA_COMORG_CODE = D.BUYER AND A.BUYER_ITEM_NO = D.BUYER_ITEM_NO AND A.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.STATUS != 'D' AND B.STATUS (+)!= 'D'
AND A.BUYER = #{st_buyer_code}
AND A.AGENT = #{st_agent_code}
AND D.DESCRIPTION_LOC LIKE #{st_description}||'%'
AND A.STATUS = #{st_req_status}
AND A.BUYER_ITEM_NO LIKE #{st_buyer_item_no}||'%'
AND D.SPECIFICATION LIKE #{st_sepc}||'%'
AND A.KEP_USER_ID = #{st_add_user_id}
AND D.MAKER_CODE = #{st_maker_code}
AND A.ITEM_TYPE = #{st_cond_item_type}
AND D.PRODUCT_CLOSE_FLAG NOT IN ('S', 'G')
AND D.STATUS != 'D' AND D.PRODUCT_CLOSE_FLAG IN ('N', 'T')
AND D.STATUS != 'D' AND D.PRODUCT_CLOSE_FLAG = 'Y'
AND D.STATUS != 'D' AND D.PRODUCT_CLOSE_FLAG = 'A'
AND D.STATUS != 'D' AND D.PRODUCT_CLOSE_FLAG = 'C'
AND D.STATUS != 'D' AND D.PRODUCT_CLOSE_FLAG = 'B'
AND D.STATUS = 'D'
AND D.CMS_CATEG_ID IN ( SELECT CMS_CATEG_ID FROM CMSCATEG CATEG WHERE CATEG.SG_ID = #{st_c_sg_id} AND CATEG.STATUS != 'D' )
) Z
WHERE Z.CONTRACT_YN = #{st_contract_yn}
ORDER BY Z.REQ_NO

mapper.update:

/* updateMasterMdcmReqRemarkAtos */
	UPDATE KEPCMSHD A 
		SET   A.ATOS_REMARK = #{st_atoa_remark}  
		 WHERE A.BUYER = #{st_buyer}                                    
		   AND A.REQ_NO = #{st_req_no}


/* updateMasterMdCmCatalogMapping */
	UPDATE KEPCMSHD A 
		SET   A.CMS_CATLG_ID = #{CMS_CATLG_ID}
		, A.CHANGE_DATE=   TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CHANGE_USER_ID= #{USR_ID}
		, A.REJECT_REMARK = ''
		, A.STATUS = 'M'
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.REQ_NO = #{REQ_NO}


/* rejectMasterMdCmCatalogMapping */
	UPDATE KEPCMSHD A 
		SET   A.STATUS  = 'B'
		, A.REJECT_REMARK = #{REJECT_REMARK}
		, A.CHANGE_DATE=   TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CHANGE_USER_ID= #{USR_ID}
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.REQ_NO = #{REQ_NO}


/* saveMasterMdCmCatalogMappingCompl */
	UPDATE KEPCMSHD A 
		SET   A.STATUS  = 'C'
		, A.CHANGE_DATE=   TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CHANGE_USER_ID= #{USR_ID}
		, A.CONFIRM_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CONFIRM_USER_ID= #{USR_ID}
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.REQ_NO = #{REQ_NO}


/* saveMasterMdCmCatalogMappingByit */
	UPDATE ICOMBYIT  A 
		SET
		  A.CMS_CATLG_ID = #{CMS_CATLG_ID}
		, A.CHANGE_DATE=   TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CHANGE_USER_ID= #{USR_ID}
		 WHERE A.BUYER = #{BYCA_COMORG_CODE}                                    
		   AND A.BUYER_ITEM_NO = #{BUYER_ITEM_NO}


/* updateMasterMdcmKEPCMSHDRemark */
	UPDATE KEPCMSHD A 
		SET   A.ATOS_REMARK  =#{ATOS_REMARK}
		, A.REJECT_REMARK = ''
		, A.STATUS = 'Q'
		, A.CHANGE_DATE=   TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CHANGE_USER_ID= #{USR_ID}
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.REQ_NO = #{REQ_NO}


/* updateMasterMdcmKEPCMSDTRevision */
	UPDATE KEPCMSDT A 
		SET   A.STATUS  ='O'
		, A.CHANGE_DATE=   TO_CHAR(SYSDATE,'YYYYMMDD')
		, A.CHANGE_USER_ID= #{USR_ID}
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.REQ_NO = #{REQ_NO}
		   AND A.REVISION = #{REVISION}

mapper.select:

/*selectMasterMdCmItemKepMailInfo*/
	SELECT SEQ
	FROM  KEP_MAIL
	WHERE SUBJECT =  #{SUBJECT}
	AND TO_CHAR(CREATE_DATE ,'YYYYMMDDHH24')  = TO_CHAR(SYSDATE ,'YYYYMMDDHH24')
	AND RECEIVE_EMAIL =#{RECEIVE_EMAIL}
	AND RECEIVE_NAME =#{RECEIVE_NAME}
